  for(let attempt=0;attempt<3 && !ok;attempt++){
    try{
      const r = await fetch(url,{headers:{'User-Agent':UA,'Referer':'https://www.bilibili.com/','Accept':'application/json'}});
      const txt = await r.text();
      if(txt.trim().startsWith('<')){ await sleep(2500); continue; }
      const j = JSON.parse(txt);
      console.log('=== '+kw+' ===');
      for(const it of (j.data?.result||[])){
        const t=(it.title||'').replace(/<[^>]+>/g,'');
        console.log([it.bvid,it.author,t,it.duration,it.play].join(' | '));
      }
      ok=true;
    }catch(e){ await sleep(2500); }
  }
  if(!ok) console.log('=== '+kw+' === FAIL');
  await sleep(1800);
}
