{"command": "cat > /tmp/fetchpage.mjs <<'EOF'
const urls = process.argv.slice(2);
const UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
for(const u of urls){
  try{
    const r=await fetch(u,{headers:{'User-Agent':UA,'Accept-Language':'zh-CN,zh;q=0.9'}});
    const t=await r.text();
    // extract title
    const m=t.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    const title=m?m[1].replace(/\s+/g,' ').trim():'(no title)';
    let body='';
    // csdn content
    const c=t.match(/<div id="content_views"[\s\S]{0,4000}?>/i);
    const idx=t.indexOf('id="content_views"');
    if(idx>0){ body=t.slice(idx, idx+6000); }
    body=body.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<style[\s\S]*?<\/style>/gi,'').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();
    console.log('URL: '+u);
    console.log('TITLE: '+title);
    console.log('BODY: '+body.slice(0,500));
    console.log('---');
  }catch(e){console.log('URL: '+u+'\nFAIL: '+e.message+'\n---');}
  await sleep(1000);
}
